pullbackChannelLinePrice = channelLineValue(pullbackChannelLine, currentBarIndex);
majorTrendLinePrice = trendLineValue(majorTrendLine, currentBarIndex);
isDuelingLinesConfluence = abs(pullbackChannelLinePrice - majorTrendLinePrice) <= confluenceTolerance
