waitForSecondEntry = pullbackIsSteep;
// second-entry stop mechanized as close-then-next-open
enterLongNextBarOpen = waitForSecondEntry && isHigherLowSignalBar[1] && open[0] < (high[1] + entryTick) && high[0] >= (high[1] + entryTick);

openPosition = (open[0] - low[0]) / (high[0] - low[0] + epsilon);
closePosition = (close[0] - low[0]) / (high[0] - low[0] + epsilon);
isBearTrendDayShape = openPosition >= nearExtremeThreshold && closePosition <= (1 - nearExtremeThreshold);
